const sg = (k) => (k < 0 ? `- ${-k}` : `+ ${k}`);
const px = rng.int(-4, 4), py = rng.int(-4, 5), m = rng.pick([-3, -2, -1, 2, 3, 4]);
const b = py - m * px;
const ys = b === 0 ? `y = ${m}x` : `y = ${m}x ${sg(b)}`;
return {
  prompt: `Write an equation of the line through $(${px}, ${py})$ with slope $${m}$.`,
  answers: [ys],
  explanation: `Point-slope form $y ${sg(-py)} = ${m}(x ${sg(-px)})$ is the same line as $${ys}$. Any equation of this line is accepted.`,
};

const sg = (k) => (k < 0 ? `- ${-k}` : `+ ${k}`);
let a = 0, b = 0;
while (a === 0 || b === 0 || a === b) { a = rng.int(-7, 7); b = rng.int(-7, 7); }
const p = -(a + b), q = a * b;
const poly = `x^{2}${p === 0 ? "" : ` ${p < 0 ? "-" : "+"} ${Math.abs(p) === 1 ? "" : Math.abs(p)}x`} ${sg(q)}`;
const f = `(x ${sg(-a)})(x ${sg(-b)})`;
return {
  prompt: `Factor $${poly}$.`,
  answers: [f],
  explanation: `Two numbers that multiply to $${q}$ and add to $${p}$: $${-a}$ and $${-b}$, so $${poly} = ${f}$. The expanded form is equivalent but isn't factored, so it only gets half credit.`,
};

const sg = (k) => (k < 0 ? `- ${-k}` : `+ ${k}`);
let a = 0, b = 0;
while (a === b) { a = rng.int(-6, 7); b = rng.int(-6, 7); }
const s = a + b, c = -(a * b);
const rhs = s === 0 ? `${c}` : `${s === 1 ? "" : s === -1 ? "-" : s}x${c === 0 ? "" : ` ${sg(c)}`}`;
return {
  prompt: `Solve $x^{2} = ${rhs}$. Give every solution.`,
  answers: [`\\{${a}, ${b}\\}`],
  explanation: `Move everything to one side and factor: $(x ${sg(-a)})(x ${sg(-b)}) = 0$, so $x = ${a}$ or $x = ${b}$. Either order works; one of the two gets half credit.`,
};

const [t, f, v] = rng.pick([
  ["\\frac{5\\pi}{6}", "cos", "-\\frac{\\sqrt{3}}{2}"],
  ["\\frac{2\\pi}{3}", "sin", "\\frac{\\sqrt{3}}{2}"],
  ["\\frac{7\\pi}{4}", "cos", "\\frac{\\sqrt{2}}{2}"],
  ["\\frac{4\\pi}{3}", "tan", "\\sqrt{3}"],
  ["\\frac{11\\pi}{6}", "sin", "-\\frac{1}{2}"],
  ["\\frac{3\\pi}{4}", "tan", "-1"],
]);
return {
  prompt: `Exact value of $\\${f} ${t}$?`,
  answers: [v],
  explanation: `Find the quadrant and the reference angle, then the sign: $\\${f} ${t} = ${v}$. A decimal is the right value but not exact, so it gets half credit.`,
};

const slopes = [-2, -1, 1, 2];
for (;;) {
  const px = rng.int(-3, 3), py = rng.pick([-3, -2, -1, 1, 2, 3]);
  const [m1, m2] = rng.shuffle(slopes).slice(0, 2);
  if (m1 === m2) continue;
  const x1 = px - py / m1, x2 = px - py / m2;
  if (Math.abs(x1) > 4.5 || Math.abs(x2) > 4.5) continue;
  const b1 = py - m1 * px, b2 = py - m2 * px;
  const line = (m, b) => {
    const mx = m === 1 ? "x" : m === -1 ? "-x" : `${m}x`;
    return b === 0 ? mx : `${mx} ${b < 0 ? "-" : "+"} ${Math.abs(b)}`;
  };
  const fr = (v) => (Number.isInteger(v) ? String(v) : (v < 0 ? "-" : "") + `\\tfrac{${Math.abs(v * 2)}}{2}`);
  return {
    prompt: `Mark where the lines $y = ${line(m1, b1)}$ and $y = ${line(m2, b2)}$ meet, and where each one crosses the $x$-axis.`,
    points: [[px, py], [x1, 0], [x2, 0]],
    labels: ["where they meet", `$y = ${line(m1, b1)}$ crosses`, `$y = ${line(m2, b2)}$ crosses`],
    curve: `${m1}*x+(${b1}); ${m2}*x+(${b2})`,
    explanation: `They meet where $${line(m1, b1)} = ${line(m2, b2)}$, so $x = ${px}$ and $y = ${py}$. Each crosses the $x$-axis where $y = 0$: $x = ${fr(x1)}$ and $x = ${fr(x2)}$.`,
  };
}

